<?php $selectedId=(int)($_GET['eval_id']??0);$myEvals=safeRun($pdo,"SELECT ev.*,s.matric_number,s.project_title,u.full_name FROM evaluations ev JOIN students s ON s.id=ev.student_id JOIN users u ON u.id=s.user_id WHERE ev.evaluator_id=? AND ev.evaluator_role='supervisor' AND ev.semester_id=? AND s.semester_id=? ORDER BY ev.status='pending' DESC,ev.created_at DESC",[$lecturerId,$currentSemesterId,$currentSemesterId])->fetchAll();$selected=null;$criteria=[];$scoreMap=[];foreach($myEvals as $ev)if((int)$ev['id']===$selectedId)$selected=$ev;if($selected){$criteria=safeRun($pdo,'SELECT * FROM rubric_criteria WHERE rubric_id=? ORDER BY sort_order,id',[$selected['rubric_id']])->fetchAll();$scoreMap=array_column(safeRun($pdo,'SELECT criteria_id,score FROM evaluation_scores WHERE evaluation_id=?',[$selectedId])->fetchAll(),'score','criteria_id');} ?>
<div class="row g-3"><div class="col-lg-4"><div class="card-fy"><div class="section-title">Supervision Evaluations</div><?php foreach($myEvals as $ev): ?><a class="d-block text-decoration-none p-2 rounded-3 mb-2" style="border:1.5px solid <?= $selectedId===(int)$ev['id']?'var(--theme)':'#eee' ?>" href="?view=evaluate-supervision&eval_id=<?= $ev['id'] ?>"><div class="d-flex justify-content-between"><strong class="small text-dark"><?= e($ev['full_name']) ?></strong><span class="badge-fy badge-<?= statusBadgeColor($ev['status']) ?>"><?= e(ucfirst($ev['status'])) ?></span></div><div class="small text-muted"><?= e($ev['project_title']) ?></div></a><?php endforeach; ?><?php if(!$myEvals): ?><p class="small text-muted">No evaluations assigned.</p><?php endif; ?></div></div><div class="col-lg-8"><?php if(!$selected): ?><div class="card-fy text-center py-5 text-muted">Select a student to evaluate.</div><?php else: ?><div class="card-fy"><div class="section-title"><?= e($selected['full_name']) ?></div><div class="small text-muted mb-3"><?= e($selected['matric_number']) ?> · <?= e($selected['project_title']) ?></div><form method="post"><?= csrfField() ?><input type="hidden" name="action" value="submit_evaluation"><input type="hidden" name="evaluation_id" value="<?= $selected['id'] ?>"><input type="hidden" name="back_to" value="evaluate-supervision"><?php foreach($criteria as $c): ?><label class="form-label small fw-semibold"><?= e($c['criteria_name']) ?> (max <?= e($c['weight']) ?>)</label><input required <?= $selected['status']==='completed'?'disabled':'' ?> type="number" min="0" max="<?= e($c['weight']) ?>" step="0.5" name="scores[<?= $c['id'] ?>]" value="<?= e($scoreMap[$c['id']]??'') ?>" class="form-control-fy w-100 mb-3"><?php endforeach; ?><label class="form-label small fw-semibold">Comments</label><textarea <?= $selected['status']==='completed'?'disabled':'' ?> name="comments" class="form-control-fy w-100 mb-3" rows="3"><?= e($selected['comments']??'') ?></textarea><?php if($selected['status']!=='completed'): ?><button class="btn-fy-orange">Submit and lock evaluation</button><?php else: ?><div class="alert alert-success mb-0">This completed evaluation is locked.</div><?php endif; ?></form></div><?php $backTo='evaluate-supervision'; require __DIR__.'/detailed-assessment.php'; endif; ?></div></div>
